import numpy as np
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
def fit(p, dS, dG):
    cols=[t**k for k in range(dS)]+[t**k*A**p for k in range(dG)]
    X=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=y-X@c; return np.mean(r**2)/np.var(y), np.round(c[dS:],4)
