 'invshift': lambda q: [np.ones_like(t), np.exp(-q[0]*t), t*np.exp(-q[1]*t), np.exp(-q[2]*t)/(t+q[3]), t**2*A**1.5],
 'sqrtt': lambda q: [np.ones_like(t), np.exp(-q[0]*t), t*np.exp(-q[1]*t), np.exp(-q[2]*t)/t, t**2*A**1.5, t**2*np.exp(-q[3]*t)],
 'Aexp': lambda q: [np.ones_like(t), np.exp(-q[0]*t), t*np.exp(-q[1]*t), np.exp(-q[2]*t)/t, t**2*A**1.5*np.exp(-q[3]*t)],
}
